mapper.select:
SELECT visitor_id, visitor_name, visitor_sex, visitor_call,
       bedroom_name, reason, visitor_date
FROM visitor WHERE visitor_id = #{visitorId}

mapper.update:
UPDATE visitor
visitor_name = #{visitorName}, visitor_sex = #{visitorSex}, visitor_call = #{visitorCall}, bedroom_name = #{bedroomName}, reason = #{reason}, visitor_date = #{visitorDate},
WHERE visitor_id = #{visitorId}
